country_event = {
	id = war_in_heaven.1000
	title = OK
	desc = OK
	is_test_event = yes

	trigger = {
		always = no
	}

	hide_window = yes

	immediate = {
		set_global_flag = sleepers_awake_happened
		set_global_flag = war_in_heaven_debug

		random_country = {
			limit = {
				is_country_type = fallen_empire
				NOT = { is_machine_empire = yes }
			}

			set_country_flag = sleepers_awake_first

			if = {
				limit = {
					is_hive_empire = no
				}
				country_event = { id = fallen_empires_awakening.3 }
			}
			else = {
				event_target:strongest_fragment = {
					country_event = { id = fallen_empires_awakening.10 }
				}
			}
		}

		# War in Heaven
		random_country = {
			limit = {
				is_country_type = fallen_empire
				NOR = {
					is_machine_empire = yes
					has_country_flag = sleepers_awake_first
				}
			}
			if = {
				limit = {
					is_hive_empire = no
				}
				set_country_flag = sleepers_awake_ancient_rival
				set_timed_country_flag = { flag = timed_ancient_rival days = 3600 }
			}
			else = {
				event_target:strongest_fragment = {
					set_country_flag = sleepers_awake_ancient_rival
					set_timed_country_flag = { flag = timed_ancient_rival days = 3600 }
				}
			}
		}
	}
}

