script:
country_event = {
	id = war_in_heaven.1
	title = OK
	desc = OK

	hide_window = yes

	trigger = {
		host_has_dlc = "Leviathans Story Pack"
		is_country_type = fallen_empire
		is_at_war = no
		fleet_power > 60000
		has_global_flag = sleepers_awake_happened
		NOT = { has_global_flag = sleepers_awake_rival_waking }
		has_country_flag = sleepers_awake_ancient_rival
		any_country = {
			is_country_type = awakened_fallen_empire
			has_country_flag = sleepers_awake_first_sleeper
		}
	}

	mean_time_to_happen = {
		years = 5
		modifier = {
			factor = 0.01
			OR = {
				has_global_flag = war_in_heaven_debug
				NOT = { has_country_flag = timed_ancient_rival }
			}
		}
	}

	immediate = {
		every_country = {
			limit = { is_country_type = default }
			set_timed_country_flag = { flag = ai_no_wars days = 3600 }
		}
		random_country = {
			limit = {
				is_country_type = awakened_fallen_empire
				has_country_flag = sleepers_awake_first_sleeper
			}
			save_global_event_target_as = FirstSleeper
			set_timed_country_flag = { flag = ai_no_wars days = 3600 }
		}
		save_global_event_target_as = SecondSleeper
		set_timed_country_flag = { flag = ai_no_wars days = 3600 }
		set_timed_country_flag = { flag = war_in_heaven_timer days = 720 }
		set_timed_country_flag = { flag = war_in_heaven_timer_2 days = 3600 }
		set_global_flag = sleepers_awake_rival_waking
		set_country_type = awakened_fallen_empire
		if = {
			limit = {
				is_hive_empire = no
			}
			change_government = {
				civics = {
					civic = civic_revanchist_fervor
					civic = civic_ancient_caches_of_technology
				}
			}
			if = {
				limit = {
					has_paragon_dlc = yes
				}
				unlock_council_slots = 2
				while = {
					count = 2
					create_leader = {
						class = scientist
						species = owner_main_species
						name = random
						skill = 10
						leader_age_min = 25
						leader_age_max = 45
					}
				}
			}
		}
		else = {
			switch = {
				trigger = has_country_flag
				fallen_empire_hive_war = {
					change_government = {
						civics = {
							civic = civic_restored_mind
							civic = civic_ancient_memories_of_war
						}
					}
				}
				fallen_empire_hive_growth = {
					change_government = {
						civics = {
							civic = civic_restored_mind
							civic = civic_ancient_memories_of_growth
						}
					}
				}
				fallen_empire_hive_control = {
					change_government = {
						civics = {
							civic = civic_restored_mind
							civic = civic_ancient_memories_of_control
						}
					}
					add_to_galactic_community = yes
					set_global_flag = control_awoke
					every_playable_country = {
						limit = {
							is_ai = no
						}
						country_event = { id = bio.3400 days = 1 }
					}
				}
			}
			change_country_flag = {
				icon = {
					category = "special"
					file = "hive_fe_flag_restored.dds"
				}
				background = {
					category = "backgrounds"
					file = "flag_BG_39.dds"
				}
				colors = {
					"light_orange"
					"dark_orange"
					"black"
					"null"
				}
			}
			every_country = {
				limit = {
					has_ai_personality = fallen_empire_hive_mind
				}
				integrate_country_effect = {
					OWNER = root
				}
			}
		}
		# Changing country type resets resources, so give them full stores
		add_awakened_fallen_empire_resources = yes
		add_awakened_fallen_empire_fleet = yes #also some more fleet

		# Establish communications / notify
		every_country = {
			limit = {
				OR = {
					is_country_type = default
					is_country_type = fallen_empire
				}
			}
			if = {
				limit = { NOT = { has_communications = root } }
				establish_communications_no_message = root
				root = { save_event_target_as = contact_empire }
				country_event = { id = action.1 }
			}
			country_event = { id = war_in_heaven.2 }
		}
		observer_event = { id = observer.75 }
	}
}

