name = war_in_heaven.4.a
trigger = {
			has_been_declared_crisis = no
			is_subject = no
			NOT = {
				any_country = {
					is_country_type = awakened_fallen_empire
					is_at_war_with = prev
				}
			}
			is_country_type = default
		}
ai_chance = {
			factor = 100
			modifier = {
				factor = 0
				OR = {
					is_homicidal = yes
					is_level_4_player_crisis = yes
					is_level_5_player_crisis = yes
				}
			}
			modifier = {
				factor = 5
				any_neighbor_country = {
					is_same_empire = event_target:FirstSleeper
				}
			}
			modifier = {
				factor = 2
				NOT = {
					any_neighbor_country = {
						is_same_empire = from
					}
				}
				any_system_within_border = {
					distance_to_empire = {
						who = from
						distance <= 2
						use_bypasses = no
						type = hyperlane
					}
				}
			}
			modifier = {
				factor = 0.5
				OR = {
					event_target:FirstSleeper = {
						is_fanatic_spiritualist = yes
						root = {
							is_spiritualist = no
						}
					}
					event_target:FirstSleeper = {
						is_fanatic_materialist = yes
						root = {
							is_materialist = no
						}
					}
				}
			}
			modifier = {
				factor = 0.5
				OR = {
					event_target:FirstSleeper = {
						has_ethic = ethic_fanatic_xenophobe
						root = {
							is_militarist = no
							is_xenophobe = no
						}
					}
					event_target:FirstSleeper = {
						is_fanatic_xenophile = yes
						root = {
							is_pacifist = no
							is_xenophile = no
						}
					}
					event_target:FirstSleeper = {
						is_hive_empire = yes
						root = {
							is_hive_empire = no
						}
					}
					event_target:FirstSleeper = {
						has_country_flag = fallen_empire_hive_war
						root = {
							is_pacifist = yes
						}
					}
				}
			}
			modifier = {
				factor = 0.1
				OR = {
					event_target:FirstSleeper = {
						has_ethic = ethic_fanatic_xenophobe
						root = {
							OR = {
								is_pacifist = yes
								is_xenophile = yes
							}
						}
					}
					event_target:FirstSleeper = {
						is_fanatic_xenophile = yes
						root = {
							OR = {
								is_militarist = yes
								is_xenophobe = yes
							}
						}
					}
					event_target:FirstSleeper = {
						is_fanatic_materialist = yes
						root = {
							is_spiritualist = yes
						}
					}
					event_target:FirstSleeper = {
						is_fanatic_spiritualist = yes
						root = {
							is_materialist = yes
						}
					}
				}
			}
		}
