country_event = {
	id = war_in_heaven.10
	title = OK
	desc = OK

	hide_window = yes
	is_triggered_only = yes

	trigger = {
		is_country_type = awakened_fallen_empire
		any_war = {
			any_war_participant = {
				prev = { #The War
					using_war_goal = {
						type = wg_war_in_heaven
						owner = prev #The War participant
					}
				}
			}
			any_war_participant = {
				is_country_type = awakened_fallen_empire
				prev = { #The War
					OR = {
						AND = {
							is_war_participant = {
								who = prev #The opposing Awakened Empire
								side = attackers
							}
							is_war_participant = {
								who = root #The dead Awakened Empire
								side = defenders
							}
						}
						AND = {
							is_war_participant = {
								who = prev #The opposing Awakened EMpire
								side = defenders
							}
							is_war_participant = {
								who = root #The dead Awakened Empire
								side = attackers
							}
						}
					}
				}
			}
		}
		has_global_flag = war_in_heaven_ongoing
		OR = {
			NOT = { exists = from }
			from = {
				NOT = { is_country_type = awakened_fallen_empire }
			}
		}
	}

	immediate = {
		set_global_flag = war_in_heaven_first_awakened_down

		random_country = {
			limit = {
				is_country_type = awakened_fallen_empire
				NOT = { is_same_value = root }
				any_war = {
					any_war_participant = {
						prev = { #The War
							using_war_goal = {
								type = wg_war_in_heaven
								owner = prev #The Participant
							}
						}
					}
				}
			}
			save_event_target_as = RemainingAwakened
		}

		every_war = { #End War in Heaven
			limit = {
				any_war_participant = {
					prev = { #The war we are iterating through
						using_war_goal = {
							type = wg_war_in_heaven
							owner = prev #The participant
						}
					}
				}
			}
			end_war_effect = yes
		}
		set_global_flag = war_in_heaven_first_awakened_down

		if = {
			limit = {
				NOT = {
					any_country = {
						any_war = {
							using_war_goal = {
								type = wg_war_in_heaven
								owner = prev
							}
						}
					}
				}
			}
			remove_global_flag = war_in_heaven_ongoing
			set_global_flag = war_in_heaven_ended
		}
		every_country = {
			limit = { is_ai = no }
			country_event = { id = war_in_heaven.11 }
		}
		observer_event = { id = observer.79 }
	}
}

